def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    total = v1 + v2 + v3
    value = total / 3
    return {
        "value": value,
        "trace": {
            "total": total,
            "count": 3,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
